fn is_palindrome(text: Vec<char>) -> bool {
    // Requires that the input vector is not empty
    // Ensures that the return value is true if the input is a palindrome, false otherwise
    // The length of the input vector is invariant during the loop
    // The loop decreases the remaining iterations
    // The characters are compared in a case-insensitive manner

    let len = text.len();
    // Ensure that the length is non-negative
    assert!(len >= 0);

    // Loop invariant: 0 <= i <= len / 2
    // Decreases: len / 2 - i
    for i in 0..len / 2 {
        // Invariant: left_char and right_char are valid indices
        let left_char = text[i];
        let right_char = text[len - 1 - i];

        // Assert that the characters are compared in a case-insensitive manner
        assert!(left_char.to_ascii_lowercase() == left_char);
        assert!(right_char.to_ascii_lowercase() == right_char);

        // Check if the characters are not equal
        if left_char.to_ascii_lowercase() != right_char.to_ascii_lowercase() {
            // If they are not equal, we can ensure that the result is false
            return false;
        }
    }
    // If we complete the loop without returning false, the text is a palindrome
    true
}